import { graphql, Link } from 'gatsby';
import React from 'react';

import Header from '../components/header';
import Layout from '../components/layout';
import SEO from '../components/seo';

const classes = {
  card: 'mt-12 bg-gray-900/80 border border-white/10 rounded-lg p-6 shadow-lg md:p-10',
  backLink:
    'inline-block text-sm font-semibold text-retroGold hover:text-retroPink',
  title: 'mt-4 text-4xl text-gray-100 font-bold',
  date: 'mt-2 text-gray-400 font-light',
  wrapper: 'mt-8 blog-content',
  nav: 'mt-10 pt-6 border-t border-white/10 flex flex-wrap justify-between gap-4',
  navLink: 'text-sm font-semibold text-retroGold hover:text-retroPink',
};

const BlogPost = ({ data, pageContext }) => {
  const post = data.markdownRemark;
  const { previous, next } = pageContext;

  return (
    <Layout>
      <Header metadata={data.site.siteMetadata} />
      <article className={classes.card}>
        <Link className={classes.backLink} to="/blog">
          &larr; All posts
        </Link>
        <h1 className={classes.title}>{post.frontmatter.title}</h1>
        <p className={classes.date}>Posted on {post.frontmatter.date}</p>
        <div
          className={classes.wrapper}
          dangerouslySetInnerHTML={{ __html: post.html }}
        />
        {(previous || next) && (
          <nav className={classes.nav}>
            <span>
              {previous && (
                <Link className={classes.navLink} to={previous.fields.slug}>
                  &larr; {previous.frontmatter.title}
                </Link>
              )}
            </span>
            <span>
              {next && (
                <Link className={classes.navLink} to={next.fields.slug}>
                  {next.frontmatter.title} &rarr;
                </Link>
              )}
            </span>
          </nav>
        )}
      </article>
    </Layout>
  );
};

export default BlogPost;

export const Head = ({ data, location }) => (
  <SEO
    title={data.markdownRemark.frontmatter.title}
    description={data.markdownRemark.frontmatter.description || data.markdownRemark.excerpt}
    pathname={location.pathname}
  />
);

export const pageQuery = graphql`
  query BlogPostBySlug($slug: String!) {
    site {
      siteMetadata {
        name
        title
        description
        about
        author
        github
        linkedin
      }
    }
    markdownRemark(fields: { slug: { eq: $slug } }) {
      id
      excerpt(pruneLength: 160)
      html
      frontmatter {
        title
        date(formatString: "MMMM DD, YYYY")
        description
      }
    }
  }
`;
